// Traduce la petición del CRM a una llamada a la API de Google Calendar.
// El CRM manda: { accion, calendarId?, desde?, hasta?, googleEventId?, evento?, meet?, invitar? }
const b = $input.first().json.body || {};
const accion = String(b.accion || '');
const CAL = encodeURIComponent(b.calendarId || 'primary');
const raiz = 'https://www.googleapis.com/calendar/v3/calendars/' + CAL;
const base = raiz + '/events';
const tz = b.zonaHoraria || 'America/Santo_Domingo';
const qs = (o) => Object.entries(o).filter(([, v]) => v !== undefined && v !== null && v !== '').map(([k, v]) => k + '=' + encodeURIComponent(v)).join('&');

// Todo el día: Google quiere fechas sueltas y el fin EXCLUSIVO (el CRM ya lo manda así).
const cuando = (valor, todo) => todo ? { date: String(valor).slice(0, 10) } : { dateTime: valor, timeZone: tz };

function cuerpo(e) {
  e = e || {};
  const out = {};
  if (e.titulo !== undefined) out.summary = e.titulo;
  if (e.descripcion !== undefined) out.description = e.descripcion || '';
  if (e.ubicacion !== undefined) out.location = e.ubicacion || '';
  if (e.inicio) out.start = cuando(e.inicio, e.todoElDia);
  if (e.fin) out.end = cuando(e.fin, e.todoElDia);
  if (Array.isArray(e.invitados)) out.attendees = e.invitados.filter(Boolean).map((email) => ({ email }));
  // Esto es lo que genera el enlace de Meet: Google crea la sala al guardar el evento.
  if (b.meet) {
    out.conferenceData = {
      createRequest: {
        requestId: 'crm-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8),
        conferenceSolutionKey: { type: 'hangoutsMeet' },
      },
    };
  }
  return out;
}

const envio = b.invitar ? 'all' : 'none';
const id = encodeURIComponent(String(b.googleEventId || ''));
let r = null;

if (accion === 'estado') {
  r = { method: 'GET', url: raiz, body: null };
} else if (accion === 'listar' && b.desde && b.hasta) {
  r = { method: 'GET', url: base + '?' + qs({ timeMin: b.desde, timeMax: b.hasta, singleEvents: 'true', showDeleted: 'true', maxResults: 2500 }), body: null };
} else if (accion === 'crear') {
  r = { method: 'POST', url: base + '?' + qs({ conferenceDataVersion: 1, sendUpdates: envio }), body: cuerpo(b.evento) };
} else if (accion === 'actualizar' && id) {
  r = { method: 'PATCH', url: base + '/' + id + '?' + qs({ conferenceDataVersion: 1, sendUpdates: envio }), body: cuerpo(b.evento) };
} else if (accion === 'borrar' && id) {
  r = { method: 'DELETE', url: base + '/' + id + '?' + qs({ sendUpdates: envio }), body: null };
}

if (!r) return [{ json: { valido: false, accion, error: 'Petición incompleta o acción desconocida: ' + accion } }];
return [{ json: { valido: true, accion, ...r, conCuerpo: r.body !== null } }];

// Devuelve al CRM siempre la misma forma, sea cual sea la acción.
const prep = $('Preparar').first().json;
const r = $input.first().json || {};
const status = Number(r.statusCode || 0);
let body = r.body || {};
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }

// Borrar algo que ya no existe en Google también es «borrado».
const ok = (status >= 200 && status < 300) || (prep.accion === 'borrar' && (status === 404 || status === 410));
if (!ok) {
  return [{ json: { ok: false, status, error: (body.error && body.error.message) || ('Google respondió ' + status) } }];
}

function evento(g) {
  g = g || {};
  const start = g.start || {};
  const end = g.end || {};
  const video = ((g.conferenceData && g.conferenceData.entryPoints) || []).find((p) => p.entryPointType === 'video');
  return {
    googleEventId: g.id,
    etag: g.etag || null,
    estado: g.status || 'confirmed',
    titulo: g.summary || '(sin título)',
    descripcion: g.description || null,
    ubicacion: g.location || null,
    inicio: start.dateTime || start.date || null,
    fin: end.dateTime || end.date || null,
    todoElDia: !!start.date,
    enlace: g.hangoutLink || (video && video.uri) || null,
    htmlLink: g.htmlLink || null,
    actualizado: g.updated || null,
    invitados: (g.attendees || []).map((a) => a.email),
  };
}

if (prep.accion === 'estado') return [{ json: { ok: true, calendario: body.summary || null, zonaHoraria: body.timeZone || null } }];
if (prep.accion === 'listar') return [{ json: { ok: true, eventos: (body.items || []).map(evento) } }];
if (prep.accion === 'borrar') return [{ json: { ok: true } }];
return [{ json: { ok: true, evento: evento(body) } }];
